        {
            int gridSize = 10;
            double growthThreshold = 0.5;

            double[,] grid = InitializeGrid(gridSize);
            SimulateGrowth(grid, growthThreshold);

            Console.WriteLine("Fractal Growth Simulation:");
            DisplayGrid(grid);
