        private static double[,] InitializeGrid(int size)
        {
            var random = new Random();
            double[,] grid = new double[size, size];

            for (int i = 0; i < size; i++)
            {
                for (int j = 0; j < size; j++)
                {
                    grid[i, j] = random.NextDouble(); // Random potential values
                }
            }

